# Import types used by the shared research state.
from typing import TypedDict, List, Dict, Any


class ResearchState(TypedDict, total=False):
    # Unique ID of the background task.
    task_id: str

    # Original research question.
    research_question: str

    # Research plan created by the Coordinator.
    research_plan: List[str]

    # Validated web sources.
    search_results: List[Dict[str, Any]]

    # Analysis generated by the Analyst.
    analysis: str

    # Evidence verification by the Fact-Checker.
    fact_check: str

    # Final Markdown report.
    final_report: str

    # Saved report location and filename.
    report_file: str
    report_filename: str

    # Workflow status and error information.
    status: str
    error: str

    # Human-readable workflow activity.
    activity_log: List[str]

    # Source validation statistics.
    total_sources: int
    accepted_sources: int
    rejected_sources: int

    # Research quality information.
    quality_score: int
    quality_feedback: str
    quality_details: Dict[str, Any]

    # Research history metadata.
    research_id: str
    research_timestamp: str
    metadata_filename: str
    metadata_file: str

    # Agent execution log IDs, keyed by agent name.
    agent_log_ids: Dict[str, str]
